  opacity: 0.85;
  inset: -22px;
}
.avatar-listening .aura-resonance-ring.mood-neutral {
  border-color: rgba(31, 213, 249, 0.4);
  animation: aura-ripple-wave 2s cubic-bezier(0, 0.2, 0.8, 1) infinite;
}
.avatar-listening .aura-resonance-ring.mood-friendly {
  border-color: rgba(16, 185, 129, 0.45);
  animation: aura-ripple-wave 2s cubic-bezier(0, 0.2, 0.8, 1) infinite;
}
.avatar-listening .aura-resonance-ring.mood-challenging {
  border-color: rgba(244, 63, 94, 0.45);
  animation: aura-ripple-wave 2s cubic-bezier(0, 0.2, 0.8, 1) infinite;
}

/* 3. THINKING: Compact Swirling Core */
.avatar-thinking .aura-stage-wrapper {
  transform: scale(0.95);
}
.avatar-thinking .aura-glow-backdrop {
  opacity: 0.7;
}

/* 4. SPEAKING: Dynamic Expansion (大声变大) */
.avatar-speaking .aura-stage-wrapper {
  transform: scale(1.1);
  box-shadow:
    0 24px 50px -10px rgba(2, 6, 23, 0.35),
    0 0 0 1.5px rgba(255, 255, 255, 0.15),
    0 0 35px rgba(31, 213, 249, 0.25);
}
.avatar-speaking .aura-glow-backdrop {
  opacity: 1;
  inset: -28px;
}
.avatar-speaking .aura-resonance-ring {
  opacity: 0.6;
  animation: aura-speaking-wave 1.4s ease-out infinite;
}

@keyframes aura-idle-breathe {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.02); }
}

@keyframes aura-ripple-wave {
  0% { transform: scale(0.96); opacity: 0.8; }
  100% { transform: scale(1.15); opacity: 0; }
}

@keyframes aura-speaking-wave {
  0% { transform: scale(1); opacity: 0.8; }
  100% { transform: scale(1.2); opacity: 0; }
}

.stage-persona {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 10px;
  z-index: 1;
}

.counterpart-name {
  font-size: 18px; /* 名字字号展开 */
  font-weight: 700;
  color: var(--ink);
  letter-spacing: -0.2px;
}

.state-indicator {
  display: flex;
  gap: 8px;
  align-items: center;
  font-size: 12px;
  color: var(--muted);
  margin-top: 8px;
  z-index: 1;
  background: #ffffff;
  padding: 5px 14px;
  border-radius: 20px;
  border: 1px solid var(--border-hairline);
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.04);
}

.state-indicator > span {
  height: 6px;
  width: 6px;
  background: #94a3b8;
  border-radius: 50%;
}

.state-listening > span {
  background: var(--emerald);
  box-shadow: 0 0 6px var(--emerald);
  animation: pulse 1s infinite;
}

.state-speaking > span {
  background: var(--blue);
  box-shadow: 0 0 6px var(--blue);
  animation: pulse 0.8s infinite;
}

/* SOUNDWAVE COMPONENT */
.sound-wave {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  height: 18px;
}

.sound-wave span {
  width: 3px;
  height: 4px;
  border-radius: 99px;
  background: currentColor;
  transition: height 0.2s ease;
}

.sound-wave-blue { color: var(--blue); }
.sound-wave-slate { color: var(--muted); }

.sound-wave.active span {
  animation: wave 1.1s ease-in-out infinite;
}

.sound-wave.active span:nth-child(1) { animation-delay: 0.1s; }
.sound-wave.active span:nth-child(2) { animation-delay: 0.3s; }
.sound-wave.active span:nth-child(3) { animation-delay: 0.5s; }
.sound-wave.active span:nth-child(4) { animation-delay: 0.15s; }
.sound-wave.active span:nth-child(5) { animation-delay: 0.4s; }
.sound-wave.active span:nth-child(6) { animation-delay: 0.25s; }
.sound-wave.active span:nth-child(7) { animation-delay: 0.45s; }

@keyframes wave {
  0%, 100% { height: 4px; }
  50% { height: 16px; }
}

.stage-bottom {
  text-align: center;
  margin-top: auto;
  padding: 20px 0;
  z-index: 2;
}

.stage-action-center {
  display: flex;
  justify-content: center;
  padding: 16px 0;
}

.stage-controls-area {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}

/* HORIZONTAL STATUS ROW IN WHITESPACE */
.recording-status-row {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 7px 18px;
  background: #ffffff;
  border: 1px solid var(--border-hairline);
  border-radius: 24px;
  box-shadow: 0 1px 4px rgba(15, 23, 42, 0.04);
}

.rec-pulse-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--crimson);
  animation: pulse 1s infinite;
}

.rec-time-text {
  font-family: var(--font-mono);
  font-size: 12.5px;
  font-weight: 600;
  color: var(--muted);
  letter-spacing: 0.5px;
}

.primary {
  background: var(--blue);
  color: white;
  border: none;
  padding: 13px 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border-radius: 30px;
  font-weight: 600;
  font-size: 14px;
  box-shadow: 0 4px 14px var(--blue-glow);
}

.primary:hover:not(:disabled) {
  background: #1d4ed8;
  transform: translateY(-1px);
}

.start-button {
  min-width: 220px;
}

.record-container {
  display: flex;
  justify-content: center;
}

.record-button {
  display: inline-flex;
  gap: 10px;
  align-items: center;
  justify-content: center;
  min-width: 230px;
  background: var(--blue);
  color: white;
  border: none;
  border-radius: 30px;
  padding: 14px 28px;
  font-weight: 600;
  font-size: 14px;
  box-shadow: 0 4px 14px var(--blue-glow);
}

.record-button:hover:not(:disabled) {
  background: #1d4ed8;
  transform: translateY(-1px);
}

.record-button.recording {
  background: #0f172a;
  color: white;
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.2);
}

.session-actions {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 14px;
  margin-top: 6px;
}

.session-actions button {
  border: 0;
  background: transparent;
  font-size: 12px;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: 8px;
}

.session-actions button:hover:not(:disabled) {
  background: rgba(15, 23, 42, 0.045);
  color: var(--ink);
}

.session-actions .reset-button {
  border-left: 1px solid var(--border-hairline);
  padding-left: 12px;
}

/* TRANSCRIPT PANEL */
.transcript-title {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  font-family: var(--font-mono);
}

.turn-count-badge {
  font-size: 11px;
  font-family: var(--font-mono);
  background: rgba(15, 23, 42, 0.04);
  padding: 3px 8px;
  border-radius: 12px;
  color: var(--muted);
}

.transcript {
  flex: 1;
  overflow-y: auto;
  padding: 14px 0;
  min-height: 250px;
}

.empty-transcript {
  text-align: center;
  padding: 65px 10px 0;
}

.empty-transcript > span {
  display: inline-grid;
  place-items: center;
  width: 52px;
  height: 52px;
  background: #ffffff;
  border: 1px solid var(--border-hairline);
  border-radius: 16px;
  color: var(--muted);
}

.empty-transcript h3 {
  font-size: 14px;
  margin: 16px 0 0;
  font-weight: 600;
  color: var(--muted);
}

/* MESSAGE BUBBLES */
.message-wrapper {
  margin-bottom: 16px;
}

.turn-divider {
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 16px 0 12px;
  position: relative;
}

.turn-divider::before {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--border-hairline);
}

.turn-divider-label {
  position: relative;
  background: var(--bg-core);
  color: var(--subtle);
  font-size: 10px;
  font-weight: 600;
  font-family: var(--font-mono);
  padding: 0 10px;
  letter-spacing: 0.3px;
}

.message {
  margin-bottom: 3px;
}

.message-header {
  display: flex;
  align-items: center;
  margin: 0 0 5px 3px;
}

.message-author {
  font-size: 10.5px;
  font-weight: 700;
  color: var(--muted);
  display: block;
  font-family: var(--font-mono);
  letter-spacing: 0.3px;
}

.message p {
  margin: 0;
  border-radius: 16px 16px 16px 4px;
  padding: 12px 16px; /* 对话气泡展开 */
  background: #ffffff;
  border: 1px solid var(--border-hairline);
  font-size: 14.5px; /* 字体适度展开，阅读极舒适 */
  line-height: 1.6;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
  color: var(--ink);
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.03);
}

.message-user {
  margin-left: 28px;
}

.message-user .message-header {
  justify-content: flex-end;
  margin-right: 3px;
}

.message-user .message-author {
  color: var(--blue);
}

.message-user p {
  background: var(--blue-soft);
  border-color: rgba(37, 99, 235, 0.16);
  border-radius: 16px 16px 4px 16px;
  color: #1e3a8a;
}

.composer {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  background: #ffffff;
  border: 1px solid var(--border-hairline);
  border-radius: 20px;
  padding: 8px 10px;
  transition: all 0.2s;
  box-shadow: 0 1px 4px rgba(15, 23, 42, 0.03);
}

.composer:focus-within {
  border-color: var(--blue);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.12);
}

.composer textarea {
  background: transparent;
  border: 0;
  resize: vertical;
  min-height: 42px;
  max-height: 150px;
  width: 100%;
  font-size: 13.5px;
  line-height: 1.5;
  color: var(--ink);
  padding: 6px 8px;
  outline: none;
}

.composer textarea::placeholder {
  color: var(--subtle);
}

.composer button {
  display: grid;
  place-items: center;
  background: var(--blue);
  color: white;
  border: 0;
  border-radius: 50%;
  height: 36px;
  width: 36px;
  flex-shrink: 0;
}

.composer button:hover:not(:disabled) {
  background: #1d4ed8;
}

.error-message {
  color: #b91c1c;
  background: #fef2f2;
  border: 1px solid #fecaca;
  border-radius: 10px;
  margin: 0 0 10px;
  padding: 9px 13px;
  font-size: 12px;
  line-height: 1.5;
}

.thinking-message {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 8px 3px;
}

.thinking-message > span {
  height: 5px;
  width: 5px;
  border-radius: 50%;
  background: var(--blue);
  animation: pulse 1s infinite;
}

.thinking-message small {
  font-size: 12px;
  color: var(--muted);
  margin-left: 6px;
}

.footer {
  display: flex;
  justify-content: space-between;
  padding: 26px 0;
  font-size: 12px;
  color: var(--subtle);
  border-top: 1px solid var(--border-hairline);
  margin-top: 44px;
}

.footer-divider {
  margin: 0 7px;
}

.setup-notice {
  margin-bottom: 18px;
  border: 1px solid #fde68a;
  border-radius: 12px;
  background: #fffbeb;
  padding: 12px 16px;
  font-size: 13px;
  line-height: 1.5;
  color: #92400e;
}

.setup-notice strong {
  color: #b45309;
}

/* REPORT LAYOUT */
.report-layout {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 36px;
}

.report-card {
  padding: 36px;
  background: #ffffff;
  border: 1px solid var(--border-hairline);
  border-radius: 18px;
}

.report-card h2 {
  font-size: 28px;
  letter-spacing: -0.6px;
  margin: 8px 0;
  color: var(--ink);
}

.report-summary {
  color: var(--ink-secondary);
  max-width: 700px;
  font-size: 14px;
  line-height: 1.6;
}

.feedback-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  margin: 26px 0;
}

.feedback-grid h3 {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 11px;
  color: var(--ink);
}

.feedback-grid div:first-child h3 svg { color: var(--emerald); }
.feedback-grid div:last-child h3 svg { color: #d97706; }

.feedback-grid p {
  font-size: 13px;
  padding: 11px 14px;
  background: #f8fafc;
  border-radius: 10px;
  margin: 0 0 7px;
  line-height: 1.5;
  color: var(--ink-secondary);
}

.suggested {
  background: #fffbeb;
  border: 1px solid #fde68a;
  padding: 22px;
  border-radius: 14px;
  margin-bottom: 26px;
}

.suggested .eyebrow {
  color: #b45309;
}

.suggested blockquote {
  font-size: 16px;
  line-height: 1.55;
  margin: 9px 0 0;
  color: #78350f;
  font-style: italic;
}

.report-side {
  align-self: center;
  text-align: center;
  padding: 24px;
}

.report-side .avatar {
  width: 220px;
  margin: auto;
}

.report-side h3 {
  font-size: 19px;
  margin: 14px 0 5px;
  color: var(--ink);
}

.report-side > span {
  font-size: 11px;
  color: var(--subtle);
  display: block;
  margin-top: 9px;
  font-family: var(--font-mono);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@keyframes pulse {
  0%, 100% { opacity: 0.4; }
  50% { opacity: 1; }
}

/* RESPONSIVE DESIGN */
@media (max-width: 1150px) {
  .app-shell { padding: 0 28px; }
  .studio-grid {
    grid-template-columns: 250px minmax(300px, 1fr) 320px;
    gap: 24px;
  }
  .scenario-panel { padding-right: 20px; }
  .transcript-panel { padding-left: 20px; }
  .avatar { width: 230px; height: 230px; }
  .aura-stage-wrapper { width: 220px; height: 220px; }
  .stage-orbit { width: 260px; height: 260px; }
  h1 { font-size: 28px; }
}

@media (max-width: 930px) {
  .studio-grid {
    grid-template-columns: 260px 1fr;
  }
  .transcript-panel {
    grid-column: 1 / -1;
    border-left: none;
    border-top: 1px solid var(--border-hairline);
    padding-left: 0;
    padding-top: 24px;
    min-height: 380px;
  }
  .report-layout { grid-template-columns: 1fr; }
  .report-side { display: none; }
}

@media (max-width: 600px) {
  .app-shell { padding: 0 16px; }
  .topbar { height: 64px; }
  .brand { font-size: 19px; }
  .page-heading { padding: 20px 0 16px; }
  h1 { font-size: 24px; }
  .session-chip { display: none; }
  .studio-grid {
    display: flex;
    flex-direction: column;
    gap: 22px;
  }
  .scenario-panel {
    border-right: none;
    padding-right: 0;
    border-bottom: 1px solid var(--border-hairline);
    padding-bottom: 18px;
  }
  .scenario-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }
  .transcript-panel {
    border-left: none;
    padding-left: 0;
    border-top: 1px solid var(--border-hairline);
    padding-top: 18px;
  }
  .avatar { width: 230px; height: 230px; }
  .aura-stage-wrapper { width: 220px; height: 220px; }
  .stage-orbit { width: 250px; height: 250px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *:before, *:after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}

/* Intro: twks-style single line that splits to the edges */
.intro{position:fixed;inset:0;z-index:50;background:#000;cursor:pointer;transition:background-color .9s ease .35s,opacity .5s ease .9s}
.intro-word{position:absolute;top:50%;color:#fff;font-weight:500;font-size:clamp(17px,1.5vw,22px);letter-spacing:.01em;white-space:nowrap;translate:0 -50%;transition:left 1s cubic-bezier(.76,0,.24,1),transform 1s cubic-bezier(.76,0,.24,1),color .6s ease .4s}
.intro-left{left:50%;transform:translateX(calc(-100% - 14px))}
.intro-right{left:calc(50% + 14px);transform:translateX(0)}
.intro-hold .intro-word{animation:intro-in .7s cubic-bezier(.2,.7,.2,1) both}
.intro-split{background:transparent;opacity:0;pointer-events:none}
.intro-split .intro-left{left:24px;transform:translateX(0)}
.intro-split .intro-right{left:calc(100% - 24px);transform:translateX(-100%)}
.intro-split .intro-word{color:var(--ink)}
@keyframes intro-in{from{opacity:0;translate:0 calc(-50% + 14px)}to{opacity:1;translate:0 -50%}}


/* Wardrobe (after Lacoste's Polo Factory: deep green, mint, oval badge) */
.wardrobe{--mint:#d5f0bd;width:100%;max-width:620px;padding:16px 18px 14px;border-radius:26px;background:#3e5c41;color:var(--mint);box-shadow:0 18px 40px rgba(40,62,40,.28)}
.wardrobe-head{display:flex;justify-content:space-between;align-items:center}
.wardrobe-badge{padding:6px 16px;border:1.5px solid currentColor;border-radius:50%;font-size:11px;font-weight:700;letter-spacing:.16em;text-transform:uppercase}
.wardrobe-count{font-size:12px;font-variant-numeric:tabular-nums;opacity:.8}
.rail{position:relative;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;margin-top:18px}
.rail::before{content:'';position:absolute;top:0;left:-6px;right:-6px;height:5px;border-radius:5px;background:linear-gradient(#e8d39a,#b8955a);box-shadow:0 2px 4px rgba(0,0,0,.25)}
.hanger{position:relative;display:flex;flex-direction:column;align-items:center;gap:4px;padding:0 2px 6px;color:var(--mint);border-radius:14px;transform-origin:50% 0;transition:translate .25s ease}
.hanger:hover{translate:0 2px}
.hanger-hook{width:58%;height:auto;margin-top:-4px}
.hanger-icon{width:100%;height:58px;padding:5px;margin-top:-6px;border-radius:14px;background:rgba(213,240,189,.1);border:1.5px solid rgba(213,240,189,.18);transition:background .25s}
.hanger-label{font-size:11px;line-height:1.15;text-align:center}
.hanger-on{animation:swing .7s ease-out}
.hanger-on .hanger-icon{background:var(--mint);border-color:var(--mint)}
.hanger-on .hanger-label{font-weight:700;color:#fff}
.hanger:focus-visible{outline:2px solid #fff;outline-offset:2px}
.wardrobe-pick{display:flex;align-items:center;gap:12px;margin-top:10px;padding-top:12px;border-top:1px solid rgba(213,240,189,.22)}
.wardrobe-arrow{display:grid;place-items:center;flex:none;width:38px;height:38px;border-radius:50%;border:1.5px solid currentColor;color:var(--mint);transition:background .2s,color .2s}
.wardrobe-arrow:hover{background:var(--mint);color:#3e5c41}
.wardrobe-text{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px;text-align:center}
.wardrobe-text strong{font-family:var(--font-display),sans-serif;font-size:21px;font-weight:800;color:#fff}
.wardrobe-text span{font-size:13px;opacity:.85}
.outfit{transform-box:fill-box;transform-origin:50% 0;animation:dress .6s cubic-bezier(.3,1.45,.5,1)}
@keyframes swing{0%{rotate:0deg}25%{rotate:7deg}55%{rotate:-4deg}80%{rotate:2deg}100%{rotate:0deg}}
@keyframes dress{from{translate:0 -36px;opacity:0;scale:1.06}to{translate:0 0;opacity:1;scale:1}}


/* Sunflower motion */
.flower-head,.petals,.eyes,.talking-mouth,.face{transform-box:fill-box;transform-origin:center}
.petals-front{animation:breathe 4.5s ease-in-out infinite}
.eyes{animation:blink 5.5s infinite}
.face{animation:pop .35s cubic-bezier(.3,1.6,.5,1)}
.face-line{fill:none;stroke:#2b1a10;stroke-width:6;stroke-linecap:round;stroke-linejoin:round}
.flower-listening .flower-head{scale:1.05;transition:scale .4s cubic-bezier(.3,1.6,.5,1)}
.flower-thinking .flower-head{animation:ponder 2.4s ease-in-out infinite}
.flower-speaking .flower-head{animation:bob .38s ease-in-out infinite alternate}
.talking-mouth{animation:talk .22s ease-in-out infinite alternate}
@keyframes sway{0%,100%{rotate:-1.6deg}50%{rotate:1.6deg}}
@keyframes breathe{0%,100%{scale:1}50%{scale:1.03}}
@keyframes blink{0%,94%,100%{scale:1 1}96%{scale:1 .1}}
@keyframes pop{from{scale:.85;opacity:.4}to{scale:1;opacity:1}}
@keyframes ponder{0%,100%{rotate:-5deg}50%{rotate:3deg}}
@keyframes bob{from{translate:0 0}to{translate:0 -6px}}
@keyframes talk{from{scale:1 .35}to{scale:1 1}}
@keyframes ring{0%{box-shadow:0 0 0 0 rgba(255,107,74,.5)}100%{box-shadow:0 0 0 22px rgba(255,107,74,0)}}
@keyframes pulse{0%,100%{opacity:.4}50%{opacity:1}}


/* Wardrobe inside the studio; the sunflower stays in front of the aura. */
body{font-family:var(--font-sans),'Segoe UI',sans-serif}
.page-heading h1{max-width:960px;font-family:var(--font-display),sans-serif;font-size:clamp(24px,3vw,40px);line-height:1.15}
