  };
}

async function setup(page: Page) {
  await page.route('**/api/status', route => route.fulfill({ json: { gemini: true, gradium: false } }));
  await page.route('**/api/converse', route => route.fulfill({ json: { reply: 'What did you learn?' } }));
}

